def clear_inference_tip_cache() -> None:
    """Clear the inference tips cache."""
    _cache_instances.clear()


def _make_cache_key(node: NodeNG, context: InferenceContext | None) -> tuple:
    """Create a hashable cache key from node and context.

    Since InferenceContext isn't hashable, we extract the relevant parts
    that make it unique for caching purposes.
    """
    if context is None:
        return (id(node), None, None, None)

    # Extract the minimal set of context attributes that make it unique
    # We use id() for non-hashable objects to maintain cache correctness
    return (
        id(node),
        context.lookupname,
        id(context.callcontext) if context.callcontext else None,
        id(context.boundnode) if context.boundnode else None,
    )


def _inference_tip_cached(func: InferFn[_NodesT]) -> InferFn[_NodesT]:
    """Cache decorator used for inference tips."""

    # Create a new LRU cache for this function if it doesn't exist
    if func not in _cache_instances:
        @lru_cache(maxsize=1000)  # Limit cache to 1000 entries per function
        def cached_func(cache_key: tuple) -> list[InferenceResult]:
            node = _NODES_BY_ID.get(cache_key[0])
            if node is None:
                return []
            # Reconstruct a minimal context if needed
            if cache_key[1] is not None:
                context = InferenceContext()
                context.lookupname = cache_key[1]
            else:
                context = None
            return list(func(node, context))

        _cache_instances[func] = cached_func

    cached_func = _cache_instances[func]

    def inner(
        node: _NodesT,
        context: InferenceContext | None = None,
        **kwargs: Any,
    ) -> Generator[InferenceResult]:
        partial_cache_key = (func, node)
        if partial_cache_key in _CURRENTLY_INFERRING:
            # If through recursion we end up trying to infer the same
            # func + node we raise here.
            raise UseInferenceDefault

        # Store node in temporary dict so we can retrieve it by id in cached_func
        _NODES_BY_ID[id(node)] = node
        try:
            _CURRENTLY_INFERRING.add(partial_cache_key)
            cache_key = _make_cache_key(node, context)
            result = cached_func(cache_key)
            yield from result
        finally:
            _CURRENTLY_INFERRING.remove(partial_cache_key)
            del _NODES_BY_ID[id(node)]

    return inner

# Temporary storage to map node ids to nodes
_NODES_BY_ID: dict[int, NodeNG] = {}
